<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth\Stub;

use DateTimeImmutable;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Device\Domain\DeviceAuthorization;
use Civi\Lughauth\Features\OAuth\Device\Domain\Gateway\DeviceAuthorizationGateway;

class InMemoryDeviceAuthorizationGateway implements DeviceAuthorizationGateway
{
    /** @var array<string, DeviceAuthorization> */
    private array $byDeviceCode = [];
    /** @var array<string, string> tenant:userCode => deviceCode */
    private array $byUserCode = [];

    public function create(DeviceAuthorization $authorization): void
    {
        $this->byDeviceCode[$authorization->deviceCode] = $authorization;
        $this->byUserCode[$authorization->tenant . ':' . $authorization->userCode] = $authorization->deviceCode;
    }

    public function findByDeviceCode(string $deviceCode): ?DeviceAuthorization
    {
        return $this->byDeviceCode[$deviceCode] ?? null;
    }

    public function findByUserCode(string $tenant, string $userCode): ?DeviceAuthorization
    {
        $deviceCode = $this->byUserCode[$tenant . ':' . $userCode] ?? null;
        return $deviceCode !== null ? ($this->byDeviceCode[$deviceCode] ?? null) : null;
    }

    public function approve(string $deviceCode, AuthenticationResult $auth): bool
    {
        $entry = $this->byDeviceCode[$deviceCode] ?? null;
        if ($entry === null) {
            return false;
        }
        $this->byDeviceCode[$deviceCode] = new DeviceAuthorization(
            deviceCode: $entry->deviceCode,
            userCode: $entry->userCode,
            tenant: $entry->tenant,
            clientId: $entry->clientId,
            scope: $entry->scope,
            audiences: $entry->audiences,
            interval: $entry->interval,
            requestedAt: $entry->requestedAt,
            expiresAt: $entry->expiresAt,
            status: 'approved',
            auth: $auth,
            lastPollAt: $entry->lastPollAt,
        );
        return true;
    }

    public function deny(string $deviceCode): bool
    {
        $entry = $this->byDeviceCode[$deviceCode] ?? null;
        if ($entry === null) {
            return false;
        }
        $this->byDeviceCode[$deviceCode] = new DeviceAuthorization(
            deviceCode: $entry->deviceCode,
            userCode: $entry->userCode,
            tenant: $entry->tenant,
            clientId: $entry->clientId,
            scope: $entry->scope,
            audiences: $entry->audiences,
            interval: $entry->interval,
            requestedAt: $entry->requestedAt,
            expiresAt: $entry->expiresAt,
            status: 'denied',
            auth: null,
            lastPollAt: $entry->lastPollAt,
        );
        return true;
    }

    public function touchPoll(string $deviceCode, DateTimeImmutable $now): void
    {
        $entry = $this->byDeviceCode[$deviceCode] ?? null;
        if ($entry === null) {
            return;
        }
        $this->byDeviceCode[$deviceCode] = new DeviceAuthorization(
            deviceCode: $entry->deviceCode,
            userCode: $entry->userCode,
            tenant: $entry->tenant,
            clientId: $entry->clientId,
            scope: $entry->scope,
            audiences: $entry->audiences,
            interval: $entry->interval,
            requestedAt: $entry->requestedAt,
            expiresAt: $entry->expiresAt,
            status: $entry->status,
            auth: $entry->auth,
            lastPollAt: $now,
        );
    }

    public function consume(string $deviceCode): void
    {
        unset($this->byDeviceCode[$deviceCode]);
    }
}
